"""Rainbow brand layer. Colours adapt to Streamlit's native light/dark theme
(Settings → Theme) by using translucent tints and inherited text colour, so
meaning never depends on colour alone (every badge also has a text label)."""
from __future__ import annotations

import streamlit as st

RAINBOW = ["#FF4D6D", "#FF9F1C", "#FFD166", "#06D6A0", "#22B8F0", "#9B5DE5"]
GRADIENT = "linear-gradient(90deg,#FF4D6D,#FF9F1C,#FFD166,#06D6A0,#22B8F0,#9B5DE5)"

CSS = f"""
<style>
:root {{ --cr-grad: {GRADIENT}; }}
.block-container {{ padding-top: 1.6rem; padding-bottom: 3rem; max-width: 1240px; }}
/* brand bar */
.cr-brand {{ display:flex; align-items:center; gap:.85rem; margin:0 0 .6rem 0; }}
.cr-logo {{ width:38px; height:38px; border-radius:11px; background:var(--cr-grad); background-size:200% 100%;
           display:grid; place-items:center; color:#fff; font-weight:800; font-size:1.05rem;
           box-shadow: inset 0 0 0 2px rgba(255,255,255,.25); animation: cr-shift 9s ease-in-out infinite alternate; }}
.cr-brand h1 {{ font-size:1.32rem; line-height:1.15; margin:0; padding:0; font-weight:750; letter-spacing:-.01em; }}
.cr-brand p {{ margin:0; font-size:.86rem; opacity:.72; }}
.cr-stripe {{ height:4px; border-radius:4px; background:var(--cr-grad); margin:.2rem 0 1.1rem 0; }}
@keyframes cr-shift {{ from {{ background-position:0% 50%; }} to {{ background-position:100% 50%; }} }}
@media (prefers-reduced-motion: reduce) {{ .cr-logo, .cr-shimmer {{ animation:none !important; }} }}
/* step header */
.cr-step {{ display:flex; align-items:baseline; gap:.6rem; margin:.1rem 0 .35rem 0; }}
.cr-step .num {{ font-weight:800; font-size:.8rem; padding:.12rem .5rem; border-radius:999px; color:#1B1530;
               background:var(--cr-c, #FFD166); }}
.cr-step h2 {{ font-size:1.25rem; margin:0; padding:0; font-weight:720; }}
.cr-lead {{ opacity:.8; margin:-.1rem 0 .9rem 0; font-size:.95rem; }}
/* badges: text + colour, never colour alone */
.cr-badge {{ display:inline-flex; align-items:center; gap:.3rem; font-size:.76rem; font-weight:650; padding:.12rem .55rem;
            border-radius:999px; border:1px solid var(--b); background:color-mix(in srgb, var(--b) 16%, transparent);
            margin:0 .25rem .25rem 0; white-space:nowrap; }}
.cr-badge .dot {{ width:.5rem; height:.5rem; border-radius:50%; background:var(--b); }}
/* cards */
.cr-card {{ border:1px solid rgba(128,128,160,.28); border-radius:.8rem; padding:.8rem .95rem; margin-bottom:.6rem;
           background: rgba(128,128,160,.05); }}
.cr-card h4 {{ margin:0 0 .25rem 0; font-size:.98rem; }}
.cr-card p {{ margin:.15rem 0; font-size:.86rem; opacity:.85; }}
.cr-accent-top {{ border-top:3px solid var(--cr-c,#22B8F0); }}
/* score */
.cr-score {{ display:flex; align-items:center; gap:1rem; }}
.cr-ring {{ --p:0; position:relative; width:92px; height:92px; flex:none; display:grid; place-items:center; }}
.cr-ring::before {{ content:""; position:absolute; inset:0; border-radius:50%;
           background: conic-gradient(var(--ring,#06D6A0) calc(var(--p)*1%), rgba(128,128,160,.22) 0);
           -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 11px), #000 calc(100% - 10px));
                   mask: radial-gradient(farthest-side, transparent calc(100% - 11px), #000 calc(100% - 10px)); }}
.cr-ring span {{ position:relative; font-weight:800; font-size:1.15rem; }}
.cr-bar {{ height:8px; border-radius:6px; background:rgba(128,128,160,.22); overflow:hidden; }}
.cr-bar > div {{ height:100%; border-radius:6px; background:var(--cr-grad); }}
.cr-muted {{ opacity:.72; font-size:.85rem; }}
.cr-diff del {{ background:rgba(255,77,109,.18); text-decoration:line-through; border-radius:3px; padding:0 2px; }}
.cr-diff ins {{ background:rgba(6,214,160,.22); text-decoration:none; border-radius:3px; padding:0 2px; }}
/* keyboard focus always visible */
a:focus-visible, button:focus-visible, [role="tab"]:focus-visible, [role="radio"]:focus-visible,
input:focus-visible, textarea:focus-visible, [tabindex]:focus-visible {{
  outline: 3px solid #22B8F0 !important; outline-offset: 2px !important; }}
section[data-testid="stSidebar"] .stRadio label p {{ font-size:.92rem; }}
div[data-testid="stChatMessage"] {{ padding:.55rem .75rem; }}
img {{ border-radius:.4rem; }}
</style>
"""


CSS = CSS.replace("</style>", '\n/* CareerRainbow studio: shared midnight + spectrum design system. */\n:root { color-scheme:dark; --cr-text:#f4f3ff; --cr-muted:#b6b5d2; --cr-line:rgba(165,150,255,.19); }\n[data-testid="stAppViewContainer"] { background:radial-gradient(ellipse at 85% 0%,rgba(97,51,185,.17),transparent 46%),radial-gradient(ellipse at 20% 75%,rgba(0,171,210,.055),transparent 40%),#0c0b19; color:var(--cr-text); }\n[data-testid="stHeader"] { background:rgba(12,11,25,.94); border-bottom:1px solid rgba(167,146,255,.10); }\n[data-testid="stMainBlockContainer"], .block-container { padding:4.7rem 2.2rem 2.8rem; max-width:1440px; }\n[data-testid="stSidebar"] { background:linear-gradient(165deg,#17122d 0%,#0e1022 100%); border-right:1px solid var(--cr-line); }\n[data-testid="stSidebar"] > div:first-child { padding-top:1.8rem; }\n[data-testid="stSidebar"] .stVerticalBlock { gap:.85rem; }\n.cr-brand { gap:.7rem; margin-bottom:1rem; }\n.cr-logo { width:48px; height:48px; border-radius:15px; flex-shrink:0; box-shadow:0 7px 24px rgba(155,93,229,.25),inset 0 0 0 2px #ffffff40; }\n.cr-brand h1 { font-size:1.2rem; color:#f4f3ff; letter-spacing:-.04em; }\n.cr-brand p { font-size:.73rem; color:#b6b5d2; opacity:1; margin-top:.3rem; }\n.cr-stripe { height:3px; opacity:.9; margin-bottom:1.25rem; }\n[data-testid="stSidebar"] [role="radiogroup"] { gap:.3rem; }\n[data-testid="stSidebar"] [role="radiogroup"] label { padding:.55rem .7rem; border:1px solid transparent; border-radius:12px; transition:background .18s,border-color .18s; }\n[data-testid="stSidebar"] [role="radiogroup"] label:hover { background:#ffffff07; border-color:var(--cr-line); }\n[data-testid="stSidebar"] [role="radiogroup"] label:has(input:checked) { background:linear-gradient(90deg,#9b5de529,#22b8f00d); border-color:#9b5de54d; box-shadow:inset 3px 0 #ad79ff; }\n[data-testid="stSidebar"] [role="radiogroup"] label p { font-size:.86rem; font-weight:550; }\n.cr-step { align-items:center; margin:.1rem 0 .65rem; gap:.8rem; }\n.cr-step .num { padding:.3rem .65rem; font-size:.7rem; text-transform:uppercase; letter-spacing:.08em; }\n.cr-step h2 { font-size:1.8rem; letter-spacing:-.04em; line-height:1.2; color:#f4f3ff; }\n.cr-lead { color:var(--cr-muted); opacity:1; font-size:.94rem; line-height:1.7; margin-bottom:1.3rem; }\n.cr-hero { position:relative; overflow:hidden; padding:2.1rem 2.3rem; border:1px solid #9b5de536; border-radius:24px; background:radial-gradient(ellipse at 95% 20%,#9b5de524,transparent 55%),linear-gradient(120deg,#1d1636,#13192d); box-shadow:0 16px 42px #0003; margin-bottom:1rem; }\n.cr-hero::before { content:""; position:absolute; top:0; left:0; right:0; height:3px; background:var(--cr-grad); }\n.cr-eyebrow { font-size:.66rem; text-transform:uppercase; letter-spacing:.18em; color:#c4b6fa; font-weight:750; margin:0 0 .9rem; }\n.cr-hero h2 { font-size:clamp(1.85rem,3.1vw,3rem); font-weight:800; line-height:1.13; letter-spacing:-.05em; margin:0 0 .8rem; padding:0; color:#faf8ff; max-width:730px; }\n.cr-gradient-text { background:var(--cr-grad); background-clip:text; -webkit-background-clip:text; color:transparent; }\n.cr-hero p { color:#bdbcd7; font-size:.94rem; line-height:1.75; max-width:680px; margin:0 0 1.2rem; }\n.cr-pills { display:flex; flex-wrap:wrap; gap:.5rem; }\n.cr-pill { border:1px solid #ffffff18; background:#ffffff05; border-radius:999px; font-size:.72rem; padding:.35rem .65rem; color:#e0dcf6; }\n.cr-section-label { color:#bcb5d8; font-weight:700; font-size:.7rem; letter-spacing:.13em; text-transform:uppercase; margin:1rem 0 .65rem; }\n.cr-route { display:flex; flex-wrap:wrap; gap:.55rem; align-items:center; padding:.9rem 1.05rem; border:1px solid var(--cr-line); background:#121224; border-radius:14px; margin:.5rem 0 1.2rem; }\n.cr-route span { font-size:.75rem; color:#bdb9d8; }\n.cr-route b { color:#f3efff; font-weight:600; }\n.cr-route i { color:#776696; font-style:normal; }\n.cr-card { background:linear-gradient(145deg,#201936,#15172a); border:1px solid var(--cr-line); border-radius:17px; padding:1.2rem; box-shadow:0 8px 24px #0002,inset 0 1px #ffffff04; color:var(--cr-text); }\n.cr-card h4 { font-size:1rem; font-weight:720; letter-spacing:-.02em; color:#f4f3ff; line-height:1.4; margin-bottom:.55rem; }\n.cr-card p { font-size:.86rem; color:#c0bdd7; opacity:1; line-height:1.65; }\n.cr-accent-top { border-top:2px solid var(--cr-c,#22B8F0); }\n.cr-entry-icon { width:43px; height:43px; display:grid; place-items:center; border:1px solid color-mix(in srgb,var(--cr-c) 35%,transparent); border-radius:13px; background:color-mix(in srgb,var(--cr-c) 12%,transparent); font-size:1.25rem; margin-bottom:.9rem; }\n[class*="st-key-entry_"] { background:linear-gradient(145deg,#201936,#15172a); border:1px solid var(--cr-line); border-radius:18px; padding:1.1rem; box-shadow:0 9px 24px #0002; }\n[class*="st-key-entry_"] .cr-card { border:0; background:none; box-shadow:none; padding:0; margin:0; min-height:174px; }\n[class*="st-key-entry_"] [data-testid="stButton"] button { margin-top:.15rem; }\n[data-testid="stButton"] button, [data-testid="stDownloadButton"] button { min-height:2.75rem; border-radius:12px; font-weight:650; border:1px solid #9b5de53b; background:linear-gradient(130deg,#28213f,#1a1c31); color:#f5f2ff; box-shadow:0 3px 0 #0002; transition:transform .15s,box-shadow .15s,border-color .15s; }\n[data-testid="stButton"] button:hover, [data-testid="stDownloadButton"] button:hover { transform:translateY(-1px); border-color:#a479ed; color:#fff; box-shadow:0 8px 20px #9b5de520; }\n[data-testid="stButton"] button[kind="primary"], [data-testid="stDownloadButton"] button[kind="primary"] { background:linear-gradient(105deg,#ff3d6e 0%,#ff9f1c 30%,#ffe14d 53%,#2ee59d 77%,#2bb8ff 100%); border:0; color:#141327; box-shadow:0 5px 21px #ff3d6e24; }\n[data-testid="stButton"] button[kind="primary"] p { color:#141327; font-weight:750; }\nbutton:disabled { opacity:.5; transform:none!important; }\n[data-testid="stTextInput"] input, [data-testid="stTextArea"] textarea, [data-testid="stNumberInput"] input { background:#141427!important; color:#f4f3ff!important; border-radius:10px; }\n[data-baseweb="select"] > div { background:#17162c!important; border-color:#9b5de52e!important; color:#f4f3ff!important; border-radius:11px; }\n[data-testid="stWidgetLabel"] p { color:#d4cfe8; font-size:.84rem; }\n[data-testid="stExpander"] { background:#141326; border:1px solid var(--cr-line); border-radius:13px; }\n[data-testid="stExpander"] summary { padding:.7rem .9rem; }\n[data-testid="stForm"] { border:1px solid var(--cr-line); border-radius:17px; padding:1.1rem; background:#141427; }\n[data-testid="stTabs"] [role="tablist"] { gap:.3rem; background:#141326; padding:.3rem; border-radius:12px; }\n[data-testid="stTabs"] [role="tab"] { border-radius:9px; padding:.4rem .85rem; color:#c3bedb; }\n[data-testid="stTabs"] [role="tab"][aria-selected="true"] { background:#9b5de52b; color:#e1c9ff; }\n[data-testid="stMetric"] { padding:1rem; background:#18152d; border:1px solid var(--cr-line); border-radius:15px; }\n[data-testid="stFileUploader"] { border-radius:15px; background:#17152c; }\n[data-testid="stChatMessage"] { background:linear-gradient(120deg,#211a39,#17182d); border:1px solid var(--cr-line); border-radius:16px; padding:.9rem; }\n.cr-badge { padding:.23rem .58rem; font-size:.71rem; background:color-mix(in srgb,var(--b) 12%,#151226); }\n.cr-muted { color:var(--cr-muted); opacity:1; }\n.cr-bar { height:7px; margin-top:.45rem; background:#ffffff0b; }\n.cr-score { padding:1.3rem; border:1px solid #06d6a036; border-radius:20px; background:linear-gradient(120deg,#13302c80,#1a1730); }\n.cr-ring { width:110px; height:110px; }\n.cr-ring span { font-size:1.45rem; }\n[data-testid="stCaptionContainer"] { color:#a5a0bf; }\nhr { border-color:#ffffff0d!important; }\n@media(max-width:900px) { [data-testid="stMainBlockContainer"],.block-container { padding:4.5rem 1.2rem 2rem; } .cr-hero { padding:1.5rem; } }\n@media(max-width:640px) { .cr-hero h2 { font-size:1.9rem; } .cr-step h2 { font-size:1.5rem; } .cr-score { gap:.7rem; padding:.85rem; } [class*="st-key-entry_"] .cr-card { min-height:0; } }\n@media(prefers-reduced-motion:reduce) { *,*::before,*::after { animation:none!important; transition:none!important; scroll-behavior:auto!important; } }\n' + "</style>")

CSS = CSS.replace("</style>", '\n[data-testid="stSidebar"] [data-testid="stMarkdownContainer"] p,\n[data-testid="stSidebar"] [role="radiogroup"] label p,\n[data-testid="stSidebar"] [role="radiogroup"] label span,\n[data-testid="stSidebar"] [data-testid="stWidgetLabel"] p,\n[data-testid="stExpander"] summary, [data-testid="stExpander"] summary p,\n[data-testid="stExpander"] summary span { color:#e1dcf3!important; }\n[data-testid="stSidebar"] [role="radiogroup"] label { padding:.4rem .7rem; width:100%; }\n[data-testid="stSidebar"] [role="radiogroup"] label:has(input:checked) p { color:#f4eaff!important; }\n[data-testid="stSelectbox"] [role="combobox"], [data-testid="stSelectbox"] input,\n[data-testid="stSelectbox"] [data-baseweb="select"],\n[data-testid="stSelectbox"] [data-baseweb="select"] > div { background:#19162d!important; color:#f4f3ff!important; }\n[data-testid="stSelectbox"] [role="combobox"] * { color:#f4f3ff!important; }\n[data-testid="stTextInput"] label p, [data-testid="stTextArea"] label p,\n[data-testid="stRadio"] label p, [data-testid="stCheckbox"] label p { color:#ded8ef!important; }\n' + "</style>")

CSS = CSS.replace("</style>", '\n[data-testid="stExpander"] summary, [data-testid="stExpander"] details > summary,\n[data-testid="stExpander"] [data-testid="stExpanderHeader"] { background:#1c1830!important; color:#e1dcf3!important; border-radius:12px; }\n[data-testid="stCaptionContainer"] p, [data-testid="stCaptionContainer"] span { color:#aaa4c1!important; }\n[data-testid="stSelectbox"] button { background:#262039!important; color:#e1dcf3!important; }\n[data-testid="stSegmentedControl"] button { background:#211b36!important; color:#cfc6e8!important; border-color:#9b5de540!important; }\n[data-testid="stSegmentedControl"] button[aria-checked="true"], [data-testid="stSegmentedControl"] button[aria-pressed="true"] { background:#7944b8!important; color:#fff!important; }\n' + "</style>")

CSS = CSS.replace("</style>", '\n/* Override native light-theme surfaces, including form submit controls. */\n[data-testid="stBaseButton-secondary"], [data-testid="stBaseButton-secondaryFormSubmit"],\n[data-testid="stFormSubmitButton"] button, [data-testid="stPopover"] button,\n[data-testid="stSegmentedControl"] button, [data-testid="stPills"] button,\n[data-testid="stDownloadButton"] button { background:#231c39!important; color:#eee8ff!important; border:1px solid #8f72bb55!important; }\n[data-testid="stFormSubmitButton"] button[kind="primaryFormSubmit"],\n[data-testid="stFormSubmitButton"] button[kind="primary"],\n[data-testid="stBaseButton-primaryFormSubmit"] { background:linear-gradient(105deg,#ff3d6e,#ff9f1c 30%,#ffe14d 53%,#2ee59d 77%,#2bb8ff)!important; color:#171228!important; border:0!important; }\n[data-testid="stFormSubmitButton"] button p { color:inherit!important; }\n[data-testid="stSegmentedControl"] button[aria-checked="true"],\n[data-testid="stSegmentedControl"] button[aria-pressed="true"] { background:#7140ad!important; color:#fff!important; }\n[data-testid="stVerticalBlockBorderWrapper"] { background:linear-gradient(145deg,#1b1730,#131426)!important; border-color:#9b5de533!important; border-radius:16px; }\n[data-testid="stExpander"] details, [data-testid="stExpander"] details>summary,\n[data-testid="stExpander"] summary, [data-testid="stExpander"] [data-testid="stExpanderDetails"] { background:#19162b!important; border-color:#9b5de533!important; }\n[data-testid="stExpander"] summary *, [data-testid="stExpander"] summary p { color:#e6dcf7!important; }\n[data-testid="stSelectbox"] button, [data-testid="stSelectbox"] [aria-label="Open"],\n[data-testid="stSelectbox"] [role="combobox"] { background:#211b35!important; color:#ece5fa!important; }\n[data-testid="stAlert"] { background:#1e1930!important; border:1px solid #9b5de536!important; border-radius:15px; }\n[data-testid="stAlert"] p, [data-testid="stAlert"] li { color:#e7dff5!important; }\n[data-testid="stDataFrame"], [data-testid="stDataEditor"] { border:1px solid #9b5de533; border-radius:12px; overflow:hidden; }\n[data-baseweb="popover"], [role="listbox"], [role="option"] { background:#211a34!important; color:#eee8ff!important; }\n' + "</style>")

